    private func roundTrip<T: Codable>(_ type:T.Type,_ data:Data) throws {
        let value=try CodableHelper.decode(type,from:data).get()
        _=try JSONEncoder().encode(value)
    }
    func testEveryProfessionalContactWireWitness() throws {
        let cases=try JSONSerialization.jsonObject(with:fixtures) as! [[String: Any]]
        for f in cases {
            let data=try JSONSerialization.data(withJSONObject:f["value"]!)
            let name=f["schema"] as! String
            let valid=f["valid"] as! Bool
            do {
                switch name {
                case "CreateProfessionalContactRequest": try roundTrip(CreateProfessionalContactRequest.self,data)
                case "OwnProfessionalContactsView": try roundTrip(OwnProfessionalContactsView.self,data)
                case "OwnerProfessionalContactView": try roundTrip(OwnerProfessionalContactView.self,data)
                case "ProfessionalContactMutationView": try roundTrip(ProfessionalContactMutationView.self,data)
                case "ProfessionalContactProblem400": try roundTrip(ProfessionalContactProblem400.self,data)
                case "ProfessionalContactProblem401": try roundTrip(ProfessionalContactProblem401.self,data)
                case "ProfessionalContactProblem403": try roundTrip(ProfessionalContactProblem403.self,data)
                case "ProfessionalContactProblem404": try roundTrip(ProfessionalContactProblem404.self,data)
                case "ProfessionalContactProblem409": try roundTrip(ProfessionalContactProblem409.self,data)
                case "ProfessionalContactProblem412": try roundTrip(ProfessionalContactProblem412.self,data)
                case "ProfessionalContactProblem413": try roundTrip(ProfessionalContactProblem413.self,data)
                case "ProfessionalContactProblem415": try roundTrip(ProfessionalContactProblem415.self,data)
                case "ProfessionalContactProblem422": try roundTrip(ProfessionalContactProblem422.self,data)
                case "ProfessionalContactProblem428": try roundTrip(ProfessionalContactProblem428.self,data)
                case "ProfessionalContactProblem429": try roundTrip(ProfessionalContactProblem429.self,data)
                case "ProfessionalContactProblem500": try roundTrip(ProfessionalContactProblem500.self,data)
                case "ProfessionalContactProblem503": try roundTrip(ProfessionalContactProblem503.self,data)
                case "PublicProfessionalContactProblem400": try roundTrip(PublicProfessionalContactProblem400.self,data)
                case "PublicProfessionalContactProblem404": try roundTrip(PublicProfessionalContactProblem404.self,data)
                case "PublicProfessionalContactProblem422": try roundTrip(PublicProfessionalContactProblem422.self,data)
                case "PublicProfessionalContactProblem429": try roundTrip(PublicProfessionalContactProblem429.self,data)
                case "PublicProfessionalContactProblem500": try roundTrip(PublicProfessionalContactProblem500.self,data)
                case "PublicProfessionalContactProblem503": try roundTrip(PublicProfessionalContactProblem503.self,data)
                case "PublicProfessionalContactView": try roundTrip(PublicProfessionalContactView.self,data)
                case "PublicProfessionalProfileLink": try roundTrip(PublicProfessionalProfileLink.self,data)
                case "PublicProfessionalProfileView": try roundTrip(PublicProfessionalProfileView.self,data)
                case "ReplaceProfessionalContactRequest": try roundTrip(ReplaceProfessionalContactRequest.self,data)
                case "StudentPersonalContactsView": try roundTrip(StudentPersonalContactsView.self,data)
                case "StudentProfessionalContactView": try roundTrip(StudentProfessionalContactView.self,data)
                default: XCTFail("Unregistered professional contact witness");continue
                }
                XCTAssertTrue(valid,"Invalid professional contact shape accepted")
            } catch {
                XCTAssertFalse(valid,"Valid professional contact shape refused")
                XCTAssertTrue(error is ProfessionalContactsWireError)
                XCTAssertFalse(String(describing:error).contains("wire_canary_sensitive"))
            }
        }
    }
    func testGeneratedStringRulesAcceptCanonicalAuthoredWitnesses() throws {
        XCTAssertEqual(try Validator.validate("Minha rede", against: CreateProfessionalContactRequest.networkLabelRule), "Minha rede")
        XCTAssertEqual(try Validator.validate("https://example.org/personal?view=profile#about", against: CreateProfessionalContactRequest.profileUrlRule), "https://example.org/personal?view=profile#about")
        XCTAssertEqual(try Validator.validate("+5511999999999", against: CreateProfessionalContactRequest.phoneNumberRule), "+5511999999999")
        XCTAssertEqual(try Validator.validate("contact_public", against: OwnerProfessionalContactView.contactIdRule), "contact_public")
        XCTAssertEqual(try Validator.validate("Minha rede", against: OwnerProfessionalContactView.networkLabelRule), "Minha rede")
        XCTAssertEqual(try Validator.validate("https://example.org/personal?view=profile#about", against: OwnerProfessionalContactView.profileUrlRule), "https://example.org/personal?view=profile#about")
        XCTAssertEqual(try Validator.validate("+5511999999999", against: OwnerProfessionalContactView.phoneNumberRule), "+5511999999999")
        XCTAssertEqual(try Validator.validate("contact_public", against: PublicProfessionalContactView.contactIdRule), "contact_public")
        XCTAssertEqual(try Validator.validate("Minha rede", against: PublicProfessionalContactView.networkLabelRule), "Minha rede")
        XCTAssertEqual(try Validator.validate("https://example.org/personal?view=profile#about", against: PublicProfessionalContactView.profileUrlRule), "https://example.org/personal?view=profile#about")
        XCTAssertEqual(try Validator.validate("+5511999999999", against: PublicProfessionalContactView.phoneNumberRule), "+5511999999999")
        XCTAssertEqual(try Validator.validate("pp_AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA", against: PublicProfessionalProfileLink.profileRefRule), "pp_AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA")
        XCTAssertEqual(try Validator.validate("https://profiles.example.org/p/pp_AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA", against: PublicProfessionalProfileLink.urlRule), "https://profiles.example.org/p/pp_AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA")
        XCTAssertEqual(try Validator.validate("Minha rede", against: ReplaceProfessionalContactRequest.networkLabelRule), "Minha rede")
        XCTAssertEqual(try Validator.validate("https://example.org/personal?view=profile#about", against: ReplaceProfessionalContactRequest.profileUrlRule), "https://example.org/personal?view=profile#about")
        XCTAssertEqual(try Validator.validate("+5511999999999", against: ReplaceProfessionalContactRequest.phoneNumberRule), "+5511999999999")
        XCTAssertEqual(try Validator.validate("contact_public", against: StudentProfessionalContactView.contactIdRule), "contact_public")
        XCTAssertEqual(try Validator.validate("Minha rede", against: StudentProfessionalContactView.networkLabelRule), "Minha rede")
        XCTAssertEqual(try Validator.validate("https://example.org/personal?view=profile#about", against: StudentProfessionalContactView.profileUrlRule), "https://example.org/personal?view=profile#about")
        XCTAssertEqual(try Validator.validate("+5511999999999", against: StudentProfessionalContactView.phoneNumberRule), "+5511999999999")
    }
    func testDirectDecoderKeepsExplicitNullDistinctFromOmission() throws {
        let data=Data(#"{"revision":"r0","contacts":[],"publicProfileLink":null}"#.utf8)
        XCTAssertThrowsError(try JSONDecoder().decode(OwnProfessionalContactsView.self,from:data))
    }
